-- Replace the whole store catalog with a fresh demo catalog.
--
-- DESTRUCTIVE: deletes every order (food, grocery, pharmacy, with their items
-- and status events), every restaurant/grocery/pharmacy store and all of their
-- products, deals, restaurant locations and delivery slots. Then seeds:
--
--   food      8 restaurants x 20 menu items (Somali, Yemeni, Levantine,
--             burgers, Italian, Chinese, Thai/Japanese, cafe)
--   grocery   8 stores x 20 products, 10 categories, 5 delivery slots each
--   pharmacy  8 stores x 20 OTC products, 10 categories
--
-- Merchant accounts that owned a store before the wipe are re-attached to the
-- new stores of the same vertical (oldest owner -> first new store), so their
-- merchant dashboards keep working.
--
-- Images: food photos hotlink TheMealDB/TheCocktailDB; grocery product photos
-- hotlink TheMealDB ingredient images. Store photos and pharmacy product
-- photos are Wikimedia Commons images copied into the public product_icons
-- bucket under catalog/ (Wikimedia rate-limits hotlinking). Credits are in
-- supabase/seed_assets/CREDITS.md.
--
-- Requires 20260926000000_add_grocery_categories.sql.

set search_path = '';

-- Remember which merchants owned stores before the wipe.
drop table if exists pg_temp.seed_previous_owners;
create temp table seed_previous_owners as
select 'restaurant'::text as vertical, owner_id, min(created_at) as first_created
from public.restaurants where owner_id is not null group by owner_id
union all
select 'grocery', owner_id, min(created_at)
from public.grocery_stores where owner_id is not null group by owner_id
union all
select 'pharmacy', owner_id, min(created_at)
from public.pharmacy_stores where owner_id is not null group by owner_id;

-- Orders first: they reference stores with ON DELETE RESTRICT.
-- *_order_items cascade from their order.
delete from public.order_status_events;
delete from public.food_orders;
delete from public.grocery_orders;
delete from public.pharmacy_orders;

-- Catalog. deal_items cascade from deals; products and slots cascade or are
-- deleted explicitly before their store.
delete from public.deals;
delete from public.restaurant_locations;
delete from public.menu_items;
delete from public.restaurants;
delete from public.grocery_products;
delete from public.grocery_delivery_slots;
delete from public.grocery_stores;
delete from public.pharmacy_products;
delete from public.pharmacy_stores;

-- Food categories: rename, add, and activate the ones the new menus use.
update public.item_categories set name = 'Burgers' where id = '823e5e31-5ce9-4b7d-a97d-3bb55e9e3b4d';
update public.item_categories set icon_url = 'https://www.themealdb.com/images/category/side.png' where id = '3bbd8109-fc36-4da8-9372-1239877d1f59';
update public.item_categories set is_active = false where id in ('b6f0dff9-bbdd-43c5-bba8-aee8799084b5', '3fcbccc0-0e64-4c74-a229-4f5ce8c39dc6');
on conflict (id) do update set name = excluded.name, icon_url = excluded.icon_url, is_active = true;
update public.item_categories set is_active = true where id in ('2b7d28fe-bf24-409b-8099-76d3fe6dcf6a', 'e1fdd703-e3af-4ffe-8263-0124b69e6add', '52627e93-5ba1-49a7-854e-ddde0ecfc09e', '41c88a46-9759-4c15-8b64-9e8f2df6e2fd', '3d1c47c5-ef62-4805-854b-b7c2f769e898', '3bbd8109-fc36-4da8-9372-1239877d1f59', 'd74ac5d4-adae-401e-88a4-aa21f084c414', '8da137ab-4309-4aa4-8967-fb82205c35d7', '2268f24f-d187-4c15-83b8-e1b8f8474acd', 'f23fae2d-30a5-43af-bdeb-472273c82eb1', '67710654-e8cb-4198-8f89-522931c20ba0', '99953348-36f2-47e4-92d7-aebdbbf1a7fa', '7ee364fa-ca84-44d8-a290-468867b5922c', '823e5e31-5ce9-4b7d-a97d-3bb55e9e3b4d', '839130e5-414f-447b-89d0-387c53403095', '7230f8c6-9104-40c5-8ce8-dd426ca5211f');

-- Restaurants (8) and menu items (20 each).

-- Grocery categories, stores (8), products (20 each) and delivery slots.
on conflict (id) do update set name = excluded.name, sort_order = excluded.sort_order, is_active = true;

-- Pharmacy categories, stores (8) and products (20 each).
on conflict (id) do update set name = excluded.name, is_active = true;

-- Re-attach previous merchant owners to the new stores.
update public.restaurants r set owner_id = o.owner_id
from (
  select owner_id, row_number() over (order by first_created, owner_id) as n
  from pg_temp.seed_previous_owners where vertical = 'restaurant'
) o
where r.id = (array['50240110-2ea6-41d5-8e7e-c83043d28a20', 'ddb136bb-972c-47f3-884b-e00847c42860', '4bbd76b6-f133-4322-8d24-12bd7269f297', 'c90a78a4-d2ab-4bca-87f7-6ab759245233', '27536340-7eb3-453f-8f4b-78d59d4a41d7', 'b15c90f1-91fa-4467-885c-c882c01e22a9', '6a17168c-82b8-4404-8dff-b8c5f0c1cdd6', '3c100130-fc0d-4b13-83ee-26988d4d8446']::uuid[])[o.n];

update public.grocery_stores s set owner_id = o.owner_id
from (
  select owner_id, row_number() over (order by first_created, owner_id) as n
  from pg_temp.seed_previous_owners where vertical = 'grocery'
) o
where s.id = (array['bakaal-hodan', 'suuqa-bakaara', 'freshmart', 'hamar-meat-fish', 'green-valley', 'city-basket', 'daily-needs', 'healthy-corner']::text[])[o.n];

update public.pharmacy_stores s set owner_id = o.owner_id
from (
  select owner_id, row_number() over (order by first_created, owner_id) as n
  from pg_temp.seed_previous_owners where vertical = 'pharmacy'
) o
where s.id = (array['shifo', 'caafimaad-plus', 'daryeel', 'citycare', 'nabad', 'medexpress', 'green-cross', 'hooyo-baby']::text[])[o.n];

drop table pg_temp.seed_previous_owners;
